}

#re0-statusbar-app[data-theme="day"] .re0-section-heading__title {
  font-style: italic;
}

#re0-statusbar-app[data-theme="night"] .re0-section-heading__title {
  text-shadow: 0 0 24px rgb(115 215 237 / 14%);
}

.re0-section-heading__description {
  max-inline-size: 68ch;
  margin: 4px 0 0;
  color: var(--re0-muted);
  font-size: 13px;
  line-height: 1.7;
}

.re0-accordion-group {
  min-inline-size: 0;
  overflow: clip;
  border: 1px solid color-mix(in srgb, var(--re0-line) 82%, transparent);
  border-radius: 16px;
  background: color-mix(in srgb, var(--re0-panel-strong) 66%, transparent);
  box-shadow: 0 10px 28px rgb(23 37 48 / 7%);
  transition: border-color 180ms ease, box-shadow 180ms ease, transform 180ms ease;
}

#re0-statusbar-app[data-theme="night"] .re0-accordion-group {
  border-radius: 4px 17px 4px 17px;
  background:
    linear-gradient(125deg, rgb(104 212 235 / 5%), transparent 38%),
    rgb(7 17 30 / 66%);
  box-shadow: inset 0 0 28px rgb(75 193 221 / 3%), 0 12px 30px rgb(0 5 15 / 18%);
}

.re0-accordion-group[data-open="true"] {
  border-color: color-mix(in srgb, var(--re0-accent) 38%, var(--re0-line));
  box-shadow: 0 16px 38px rgb(26 47 61 / 12%);
}

.re0-accordion-group__trigger {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, .72fr) minmax(170px, 1fr) auto;
  align-items: center;
  gap: 14px;
  inline-size: 100%;
  min-block-size: 58px;
  padding: 11px 15px;
  border: 0;
  color: var(--re0-ink);
  text-align: start;
  background: transparent;
  cursor: pointer;
}

.re0-accordion-group__trigger::before {
  content: "";
  position: absolute;
  inset: 10px auto 10px 0;
  inline-size: 2px;
  border-radius: 99px;
  background: var(--re0-accent);
  opacity: 0;
  transform: scaleY(.25);
  transition: opacity 180ms ease, transform 220ms ease;
}

.re0-accordion-group[data-open="true"] .re0-accordion-group__trigger::before {
  opacity: 1;
  transform: scaleY(1);
}

.re0-accordion-group__heading {
  display: flex;
  align-items: center;
  gap: 9px;
  min-inline-size: 0;
}

.re0-accordion-group__heading strong {
  overflow-wrap: anywhere;
  font-size: 15px;
  font-weight: 680;
}

.re0-accordion-group__summary {
  min-inline-size: 0;
  overflow: hidden;
  color: var(--re0-muted);
  font-family: "Segoe UI", "Noto Sans SC", sans-serif;
  font-size: 11px;
  line-height: 1.45;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.re0-accordion-group__chevron {
