  color: var(--re0-accent);
  font: 700 17px/1 "Segoe UI", sans-serif;
  transform: rotate(0deg);
  transition: transform 220ms cubic-bezier(.2, .75, .2, 1), background-color 180ms ease;
}

.re0-accordion-group[data-open="true"] .re0-accordion-group__chevron {
  background: color-mix(in srgb, var(--re0-accent) 12%, transparent);
  transform: rotate(180deg);
}

.re0-accordion-group__body {
  padding: 4px 15px 16px;
  border-block-start: 1px solid color-mix(in srgb, var(--re0-line) 62%, transparent);
  animation: re0-group-open 240ms cubic-bezier(.2, .74, .2, 1) both;
}

.re0-group-stack {
