<body>
<div data-re0-statusbar-mount>
<main id="re0-statusbar-app" aria-live="polite" aria-busy="true"></main>
<div id="re0-statusbar-overlay-root" hidden></div>
<noscript>此状态栏需要启用 JavaScript。</noscript>
</div>
<script>
(() => {
'use strict';

const DECLARED_DOMAIN_COUNTS = Object.freeze({
  世界: 20,
  主角档案: 58,
  轮回: 25,
  关系: 31,
  事件: 13,
  线索: 6,
  资产: 17,
  规则: 2,
});

const ABILITY_CATEGORIES = Object.freeze([
  '加护',
  '权能',
  '魔法',
  '精灵术',
  '种族能力',
  '武技',
  '一般技能',
]);

const FIELD_GROUPS = Object.freeze([
  { domain: '世界', base: '世界.当前时间', fields: ['规范日期', '时段', '时间层', '轮回分支'] },
  { domain: '世界', base: '世界.当前地点', fields: ['国家', '地区', '场所', '具体位置'] },
  { domain: '世界', base: '世界.环境', fields: ['天气', '光照', '描述'] },
  { domain: '世界', base: '世界', fields: ['危机等级'] },
  { domain: '世界', base: '世界.动向.{事件ID}', fields: ['标题', '阶段', '类型', '地点', '描述'] },
  { domain: '世界', base: '世界.势力态势.{势力名称}', fields: ['立场', '状态', '描述'] },

  {
    domain: '主角档案',
    base: '主角档案',
    fields: [
      '主角锁定', '姓名', '角色类型', '性别', '年龄阶段', '种族', '身份', '阵营',
      '容貌', '衣着', '生存状态', '生命', '体力', '魔力', '精神稳定', '门状态',
      '门负荷', '魔女余香',
    ],
  },
  { domain: '主角档案', base: '主角档案.伤势.{伤势ID}', fields: ['部位', '程度', '描述'] },
  { domain: '主角档案', base: '主角档案.异常状态.{状态ID}', fields: ['类型', '剩余表现', '描述'] },
  { domain: '主角档案', base: '主角档案', fields: ['当前形态'] },
  { domain: '主角档案', base: '主角档案.战力等阶', fields: ['阶数', '位阶', '可战状态', '生效条件'] },
  {
    domain: '主角档案',
    base: '主角档案.能力.{类别}.{能力ID}',
    fields: ['状态', '可用性', '消耗或冷却', '描述'],
    variants: { 类别: ABILITY_CATEGORIES },
  },
  { domain: '主角档案', base: '主角档案', fields: ['当前目标'] },

  { domain: '轮回', base: '轮回', fields: ['世界重启次数', '当前轮回编号'] },
  { domain: '轮回', base: '轮回.存档点', fields: ['有效', '创建时间'] },
  {
    domain: '轮回',
    base: '轮回.存档点.状态快照',
    fields: ['世界', '主角档案', '关系', '事件', '线索', '资产'],
    deep: true,
  },
  { domain: '轮回', base: '轮回.最近一次重启', fields: ['死亡事件ID', '重启编号', '触发时间', '恢复结果'] },
  {
    domain: '轮回',
    base: '轮回.菜月昴死亡记录.{死亡ID}',
    fields: [
      '重启编号', '死亡时规范日期与时段', '死亡时地点', '直接原因',
      '死亡经过与最后行动', '在场或相关人物', '触发前轮回分支', '本轮遗留情报',
    ],
  },
  { domain: '轮回', base: '轮回.最近一次死亡', fields: ['死亡ID', '直接原因', '死亡经过'] },

  {
    domain: '关系',
    base: '关系.伴侣.{姓名}',
    fields: ['关系阶段', '亲密度', '立场', '生存状态', '当前地点', '当前行动'],
  },
  {
    domain: '关系',
    base: '关系.契约伙伴.{姓名}',
    fields: ['契约状态', '关系阶段', '信任', '立场', '生存状态', '当前地点', '当前行动'],
  },
  {
    domain: '关系',
    base: '关系.人物.{姓名}',
    fields: [
      '身份', '阵营', '关系阶段', '立场', '好感', '信任', '生存状态',
      '生命', '魔力', '当前地点', '当前行动', '当前形态',
    ],
  },
  { domain: '关系', base: '关系.人物.{姓名}.伤势.{伤势ID}', fields: ['部位', '程度', '描述'] },
  { domain: '关系', base: '关系.人物.{姓名}.异常状态.{状态ID}', fields: ['类型', '剩余表现', '描述'] },

  {
    domain: '事件',
    base: '事件.进行中.{事件ID}',
    fields: ['标题', '类型', '阶段', '状态', '地点', '参与者', '目标', '描述'],
  },
  { domain: '事件', base: '事件.近期记录.{事件ID}', fields: ['标题', '结果', '规范日期', '参与者', '描述'] },

  { domain: '线索', base: '线索.当前线索.{线索ID}', fields: ['标题', '状态', '关联事件', '描述', '下一步'] },
  { domain: '线索', base: '线索', fields: ['未解问题'] },

  { domain: '资产', base: '资产.货币.{货币类型}', fields: ['数量', '持有者', '存放位置'] },
  { domain: '资产', base: '资产.物品.{物品ID}', fields: ['名称', '数量', '持有者', '存放位置', '描述'] },
  { domain: '资产', base: '资产.装备.{装备ID}', fields: ['名称', '持有者', '装备状态', '损耗', '当前效果'] },
  { domain: '资产', base: '资产.据点与存放.{据点ID}', fields: ['名称', '位置', '控制者', '状态'] },

  { domain: '规则', base: '规则', fields: ['schema版本', '初始化完成'] },
]);

function expandVariants(template, variants = {}) {
  let results = [template];
  for (const [name, values] of Object.entries(variants)) {
    const token = `{${name}}`;
    results = results.flatMap((candidate) =>
      candidate.includes(token)
        ? values.map((value) => candidate.replaceAll(token, value))
        : [candidate],
    );
  }
  return results;
}

function expandDeclaredPaths() {
  return FIELD_GROUPS.flatMap((group) =>
    expandVariants(group.base, group.variants).flatMap((base) =>
      group.fields.map((field) => `${base}.${field}${group.deep ? '.**' : ''}`),
    ),
  );
}

const DECLARED_PATHS = Object.freeze(expandDeclaredPaths());

function isPlaceholder(segment) {
  return /^\{[^{}]+\}$/.test(segment);
}

function matchesPattern(pattern, path) {
  const expected = pattern.split('.');
  const actual = path.split('.');
  const deep = expected.at(-1) === '**';
  const expectedLength = deep ? expected.length - 1 : expected.length;
  if ((!deep && actual.length !== expectedLength) || (deep && actual.length < expectedLength)) {
    return false;
  }

  for (let index = 0; index < expectedLength; index += 1) {
    if (!isPlaceholder(expected[index]) && expected[index] !== actual[index]) return false;
    if (isPlaceholder(expected[index]) && !actual[index]) return false;
  }
  return true;
}

function isDeclaredPath(path) {
  if (typeof path !== 'string' || !path) return false;
  return DECLARED_PATHS.some((pattern) => matchesPattern(pattern, path));
}


const NAV_SECTIONS = Object.freeze([
  { id: 'overview', label: '概览', glyph: '✦' },
  { id: 'protagonist', label: '主角', glyph: '♙' },
  { id: 'world', label: '世界', glyph: '⌖' },
  { id: 'relations', label: '人际', glyph: '♢' },
  { id: 'loop', label: '轮回', glyph: '∞' },
  { id: 'events', label: '事件', glyph: '◇' },
  { id: 'clues', label: '线索', glyph: '⌕' },
  { id: 'assets', label: '行囊', glyph: '▣' },
  { id: 'diagnostics', label: '诊断', glyph: '⚙' },
]);

function asRecord(value) {
  return value && typeof value === 'object' && !Array.isArray(value) ? value : {};
}

function asList(value) {
  return Array.isArray(value) ? value : [];
}

function asText(value, fallback = '未记录') {
  return typeof value === 'string' && value.trim() ? value.trim() : fallback;
}

function clampMeter(value, fallback = 0) {
  const number = Number(value);
  return Number.isFinite(number) ? Math.min(100, Math.max(0, number)) : fallback;
}

function clampSignedMeter(value, fallback = 0) {
  const number = Number(value);
  return Number.isFinite(number) ? Math.min(100, Math.max(-100, number)) : fallback;
}

function resolveTheme(period, preference = 'auto') {
  const normalizedPeriod = asText(period, '时段未详');
  const transition = normalizedPeriod === '黎明'
    ? 'dawn'
    : normalizedPeriod === '傍晚'
      ? 'dusk'
      : 'steady';
  const automatic = ['夜间', '深夜', '凌晨'].includes(normalizedPeriod) ? 'night' : 'day';
  const normalizedPreference = ['day', 'night'].includes(preference) ? preference : 'auto';
  return {
    mode: normalizedPreference === 'auto' ? automatic : normalizedPreference,
    automatic,
    transition,
    preference: normalizedPreference,
    period: normalizedPeriod,
  };
}

function firstGrapheme(name) {
  const normalized = asText(name, '').trim();
  if (!normalized) return '?';
  if (typeof Intl !== 'undefined' && typeof Intl.Segmenter === 'function') {
    const segment = new Intl.Segmenter('zh-CN', { granularity: 'grapheme' })
      .segment(normalized)[Symbol.iterator]().next().value;
    if (segment?.segment) return segment.segment;
  }
  return Array.from(normalized)[0] || '?';
}

function flattenLeaves(value, prefix = '', output = []) {
  if (Array.isArray(value)) {
    if (prefix) output.push({ path: prefix, value });
    return output;
  }
  if (value && typeof value === 'object') {
    for (const [key, child] of Object.entries(value)) {
      flattenLeaves(child, prefix ? `${prefix}.${key}` : key, output);
    }
    return output;
  }
  if (prefix) output.push({ path: prefix, value });
  return output;
}

function collectUnknownPaths(statData) {
  return flattenLeaves(asRecord(statData)).filter((entry) => !isDeclaredPath(entry.path));
}

function recordEntries(value, category) {
  return Object.entries(asRecord(value)).map(([id, item]) => ({
    id,
    category,
    ...asRecord(item),
  }));
}

function relationshipEntries(relations) {
  return [
    ...recordEntries(relations.伴侣, '伴侣').map((person) => ({ name: person.id, ...person })),
    ...recordEntries(relations.契约伙伴, '契约伙伴').map((person) => ({ name: person.id, ...person })),
    ...recordEntries(relations.人物, '人物').map((person) => ({ name: person.id, ...person })),
  ];
}

function buildInstruments(protagonist) {
  return [
    { id: 'life', label: '生命', value: clampMeter(protagonist.生命), tone: 'vital' },
    { id: 'stamina', label: '体力', value: clampMeter(protagonist.体力), tone: 'stamina' },
    { id: 'mana', label: '魔力', value: clampMeter(protagonist.魔力), tone: 'mana' },
    { id: 'spirit', label: '精神稳定', value: clampMeter(protagonist.精神稳定), tone: 'spirit' },
    { id: 'gate', label: '门负荷', value: clampMeter(protagonist.门负荷), tone: 'risk', inverse: true },
    { id: 'scent', label: '魔女余香', value: clampMeter(protagonist.魔女余香), tone: 'witch', inverse: true },
  ];
}

function buildAlerts(world, protagonist, events) {
  const alerts = [];
  if (!['无', '低'].includes(asText(world.危机等级, '无'))) {
    alerts.push({ kind: 'crisis', title: `${world.危机等级}危机`, detail: asText(world.环境?.描述, '周遭风险正在升高') });
  }
  for (const [id, injury] of Object.entries(asRecord(protagonist.伤势))) {
    const item = asRecord(injury);
    alerts.push({ kind: 'injury', title: `${asText(item.部位, id)} · ${asText(item.程度)}`, detail: asText(item.描述, '伤势详情未记录') });
  }
  for (const [id, abnormal] of Object.entries(asRecord(protagonist.异常状态))) {
    const item = asRecord(abnormal);
    alerts.push({ kind: 'abnormal', title: asText(item.类型, id), detail: asText(item.剩余表现) });
  }
  for (const [id, event] of Object.entries(asRecord(events.进行中))) {
    const item = asRecord(event);
    if (['紧急', '危险', '失控'].some((word) => asText(item.状态, '').includes(word))) {
      alerts.push({ kind: 'event', title: asText(item.标题, id), detail: asText(item.状态) });
    }
  }
  return alerts.slice(0, 3);
}

function buildOverview(world, protagonist, loop, events) {
  const time = asRecord(world.当前时间);
  const location = asRecord(world.当前地点);
  const environment = asRecord(world.环境);
  return {
    time: {
      date: asText(time.规范日期),
      period: asText(time.时段, '时段未详'),
      layer: asText(time.时间层, '主线'),
      branch: asText(time.轮回分支, 'B00'),
    },
    location: [location.国家, location.地区, location.场所, location.具体位置]
      .map((value) => asText(value, ''))
      .filter(Boolean),
    environment: {
      weather: asText(environment.天气),
      light: asText(environment.光照),
      description: asText(environment.描述),
    },
    crisis: asText(world.危机等级, '无'),
    protagonist: {
      name: asText(protagonist.姓名),
      identity: asText(protagonist.身份),
      status: asText(protagonist.生存状态, '存活'),
      form: asText(protagonist.当前形态, '常态'),
      locked: protagonist.主角锁定 === true,
    },
    instruments: buildInstruments(protagonist),
    target: asText(protagonist.当前目标, '无'),
    loop: {
      number: Math.max(0, Number(loop.当前轮回编号) || 0),
      restarts: Math.max(0, Number(loop.世界重启次数) || 0),
      checkpointValid: asRecord(loop.存档点).有效 === true,
    },
    alerts: buildAlerts(world, protagonist, events),
  };
}

function abilityGroups(protagonist) {
  const abilities = asRecord(protagonist.能力);
  return ABILITY_CATEGORIES.map((category) => ({
    category,
    items: recordEntries(abilities[category], category),
  }));
}

function buildHudModel(statData, uiState = {}) {
  const root = asRecord(statData);
  const world = asRecord(root.世界);
  const protagonist = asRecord(root.主角档案);
  const loop = asRecord(root.轮回);
  const relations = asRecord(root.关系);
  const events = asRecord(root.事件);
  const clues = asRecord(root.线索);
  const assets = asRecord(root.资产);
  const rules = asRecord(root.规则);
  const time = asRecord(world.当前时间);

  return Object.freeze({
    readOnly: true,
    theme: resolveTheme(time.时段, uiState.themePreference),
    sections: NAV_SECTIONS,
    overview: buildOverview(world, protagonist, loop, events),
    protagonist: {
      raw: protagonist,
      injuries: recordEntries(protagonist.伤势, '伤势'),
      abnormalities: recordEntries(protagonist.异常状态, '异常状态'),
      abilities: abilityGroups(protagonist),
    },
    world: {
      raw: world,
      movements: recordEntries(world.动向, '动向'),
      factions: recordEntries(world.势力态势, '势力态势'),
    },
    loop: {
      raw: loop,
      deaths: recordEntries(loop.菜月昴死亡记录, '死亡记录'),
    },
    relations: {
      raw: relations,
      people: relationshipEntries(relations),
    },
    events: {
      raw: events,
      active: recordEntries(events.进行中, '进行中'),
      recent: recordEntries(events.近期记录, '近期记录'),
    },
    clues: {
      raw: clues,
      current: recordEntries(clues.当前线索, '当前线索'),
      questions: asList(clues.未解问题),
    },
    assets: {
      raw: assets,
      currencies: recordEntries(assets.货币, '货币'),
      items: recordEntries(assets.物品, '物品'),
      equipment: recordEntries(assets.装备, '装备'),
      locations: recordEntries(assets.据点与存放, '据点与存放'),
    },
    rules,
    diagnostics: {
      schemaVersion: asText(rules.schema版本),
      initialized: rules.初始化完成 === true,
      declaredDomainCounts: DECLARED_DOMAIN_COUNTS,
      unknown: collectUnknownPaths(root),
    },
  });
}


const DATABASE_VERSION = 1;
const STORE_NAME = 'portraits';
const MAX_SOURCE_BYTES = 20 * 1024 * 1024;

function normalizePortraitName(name) {
  const normalized = String(name ?? '')
    .normalize('NFKC')
    .replace(/\s+/gu, ' ')
    .trim();
  return normalized || '未命名';
}

function escapeIdentitySegment(value) {
  return String(value).replaceAll('%', '%25').replaceAll(':', '%3A');
}

function portraitKeys({ namespace = 'person', name, chatId = '' }) {
  const safeNamespace = namespace === 'protagonist' ? 'protagonist' : 'person';
  const safeName = escapeIdentitySegment(normalizePortraitName(name));
  const shared = `${safeNamespace}:${safeName}`;
  return {
    shared,
    override: String(chatId).trim()
      ? `chat:${encodeURIComponent(String(chatId).trim())}:${shared}`
      : null,
  };
}

function portraitScopeOptions(chatId = '') {
  return {
    selected: 'shared',
    overrideDisabled: !String(chatId).trim(),
  };
}

function validatePortraitUrl(input) {
  const value = String(input ?? '').trim();
  try {
    const parsed = new URL(value);
    if (parsed.protocol !== 'https:') {
      return { ok: false, error: '头像 URL 必须使用 HTTPS' };
    }
    if (!parsed.hostname || parsed.username || parsed.password) {
      return { ok: false, error: '头像 URL 不能包含账号信息' };
    }
    return { ok: true, value: parsed.href };
  } catch {
    return { ok: false, error: '请输入有效的 HTTPS 图片 URL' };
  }
}

function usablePortrait(record) {
  if (!record || typeof record !== 'object') return null;
  if (record.kind === 'url') {
    const validation = validatePortraitUrl(record.value);
    return validation.ok ? { ...record, value: validation.value } : null;
  }
  if (record.kind === 'blob' && typeof Blob !== 'undefined' && record.value instanceof Blob) {
    return record.value.type.startsWith('image/') ? record : null;
  }
  return null;
}

function resolvePortrait({ name, shared = null, override = null }) {
  const chatPortrait = usablePortrait(override);
  if (chatPortrait) return { ...chatPortrait, source: 'override' };
  const sharedPortrait = usablePortrait(shared);
  if (sharedPortrait) return { ...sharedPortrait, source: 'shared' };
  return {
    kind: 'initial',
    initial: firstGrapheme(normalizePortraitName(name)),
    source: 'fallback',
  };
}

function requestResult(request) {
  return new Promise((resolve, reject) => {
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error || new Error('IndexedDB 请求失败'));
  });
}

function transactionDone(transaction) {
  return new Promise((resolve, reject) => {
    transaction.oncomplete = () => resolve();
    transaction.onerror = () => reject(transaction.error || new Error('头像存储事务失败'));
    transaction.onabort = () => reject(transaction.error || new Error('头像存储事务已取消'));
  });
}

function validateStoredPortrait(record) {
  if (!record || typeof record !== 'object') throw new TypeError('头像记录无效');
  if (record.kind === 'url') {
    const validation = validatePortraitUrl(record.value);
    if (!validation.ok) throw new TypeError(validation.error);
    return { ...record, value: validation.value };
  }
  if (record.kind === 'blob' && typeof Blob !== 'undefined' && record.value instanceof Blob) {
    if (!record.value.type.startsWith('image/')) throw new TypeError('本地头像必须是图片');
    return record;
  }
  throw new TypeError('头像记录必须是 HTTPS URL 或图片 Blob');
}

function createPortraitRepository({
  indexedDB = globalThis.indexedDB,
  databaseName = 're0-statusbar',
} = {}) {
  if (!indexedDB || typeof indexedDB.open !== 'function') {
    throw new Error('当前环境不支持 IndexedDB，无法保存头像');
  }

  const database = new Promise((resolve, reject) => {
    const request = indexedDB.open(databaseName, DATABASE_VERSION);
    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        db.createObjectStore(STORE_NAME, { keyPath: 'key' });
      }
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error || new Error('无法打开头像库'));
    request.onblocked = () => reject(new Error('头像库正在被另一页面升级'));
  });

  return Object.freeze({
    async get(key) {
      if (!key) return null;
      const db = await database;
      const transaction = db.transaction(STORE_NAME, 'readonly');
      const result = await requestResult(transaction.objectStore(STORE_NAME).get(key));
      return result || null;
    },

    async put(key, record) {
      if (!key) throw new TypeError('头像键不能为空');
      const validated = validateStoredPortrait(record);
      const db = await database;
      const transaction = db.transaction(STORE_NAME, 'readwrite');
      transaction.objectStore(STORE_NAME).put({
        ...validated,
        key,
        updatedAt: new Date().toISOString(),
      });
      await transactionDone(transaction);
      return this.get(key);
    },

    async remove(key) {
      if (!key) return;
      const db = await database;
      const transaction = db.transaction(STORE_NAME, 'readwrite');
      transaction.objectStore(STORE_NAME).delete(key);
      await transactionDone(transaction);
    },

    async close() {
      const db = await database;
      db.close();
    },
  });
}

function boundedNumber(value, minimum, maximum, fallback) {
  const number = Number(value);
  return Number.isFinite(number) ? Math.min(maximum, Math.max(minimum, number)) : fallback;
}

async function decodeBlob(blob, { createImageBitmap, document, URL: UrlApi }) {
  if (!(blob instanceof Blob) || !blob.type.startsWith('image/')) {
    throw new TypeError('请选择有效的图片文件');
  }
  if (blob.size > MAX_SOURCE_BYTES) throw new RangeError('图片不能超过 20 MB');

  if (typeof createImageBitmap === 'function') {
    return createImageBitmap(blob);
  }
  if (!document?.createElement || !UrlApi?.createObjectURL) {
    throw new Error('当前环境无法解码图片');
  }

  const image = document.createElement('img');
  const objectUrl = UrlApi.createObjectURL(blob);
  try {
    await new Promise((resolve, reject) => {
      image.onload = resolve;
      image.onerror = () => reject(new Error('无法解码所选图片'));
      image.src = objectUrl;
    });
    return image;
  } finally {
    UrlApi.revokeObjectURL(objectUrl);
  }
}

function canvasToWebp(canvas, quality = 0.88) {
  if (typeof canvas.convertToBlob === 'function') {
    return canvas.convertToBlob({ type: 'image/webp', quality });
  }
  return new Promise((resolve, reject) => {
    canvas.toBlob(
      (blob) => blob ? resolve(blob) : reject(new Error('浏览器无法生成 WebP 头像')),
      'image/webp',
      quality,
    );
  });
}

async function cropPortrait({
  source,
  zoom = 1,
  offsetX = 0,
  offsetY = 0,
  size = 512,
  document = globalThis.document,
  createImageBitmap = globalThis.createImageBitmap,
  URL: UrlApi = globalThis.URL,
} = {}) {
  if (!document?.createElement) throw new Error('当前环境不支持头像裁切');
  const outputSize = Math.round(boundedNumber(size, 128, 1024, 512));
  const bitmap = await decodeBlob(source, { createImageBitmap, document, URL: UrlApi });
  const width = Number(bitmap.width || bitmap.naturalWidth);
  const height = Number(bitmap.height || bitmap.naturalHeight);
  if (!(width > 0 && height > 0)) {
    bitmap.close?.();
    throw new Error('图片尺寸无效');
  }

  const canvas = document.createElement('canvas');
  canvas.width = outputSize;
  canvas.height = outputSize;
  const context = canvas.getContext('2d', { alpha: false });
  if (!context) {
    bitmap.close?.();
    throw new Error('当前环境无法创建头像画布');
  }

  const scale = Math.max(outputSize / width, outputSize / height)
    * boundedNumber(zoom, 1, 4, 1);
  const drawnWidth = width * scale;
  const drawnHeight = height * scale;
  const overflowX = Math.max(0, drawnWidth - outputSize);
  const overflowY = Math.max(0, drawnHeight - outputSize);
  const x = -overflowX / 2 + boundedNumber(offsetX, -1, 1, 0) * overflowX / 2;
  const y = -overflowY / 2 + boundedNumber(offsetY, -1, 1, 0) * overflowY / 2;

  context.fillStyle = '#101421';
  context.fillRect(0, 0, outputSize, outputSize);
  context.imageSmoothingEnabled = true;
  context.imageSmoothingQuality = 'high';
  context.drawImage(bitmap, x, y, drawnWidth, drawnHeight);

  try {
    const blob = await canvasToWebp(canvas);
    if (!(blob instanceof Blob) || blob.size === 0) throw new Error('生成的头像为空');
    return blob;
  } finally {
    bitmap.close?.();
  }
}


function safeCall(fn) {
  if (!fn) return null;
  try {
    return fn();
  } catch {
    return null;
  }
}

function asErrorMessage(error) {
  return error instanceof Error ? error.message : String(error);
}

function scopeHasRuntime(scope) {
  if (!scope || (typeof scope !== 'object' && typeof scope !== 'function')) return false;
  try {
    return typeof scope.getVariables === 'function'
      || typeof scope.TavernHelper?.getVariables === 'function'
      || typeof scope.Mvu?.getMvuData === 'function';
  } catch {
    return false;
  }
}

function discoverRuntimeScope(start = globalThis) {
  const candidates = [start];
  try {
    if (start.parent && start.parent !== start) candidates.push(start.parent);
  } catch {}
  try {
    if (start.top && !candidates.includes(start.top)) candidates.push(start.top);
  } catch {}
  return candidates.find(scopeHasRuntime) || start;
}

function createRuntimeBridge(scope = globalThis) {
  const callable = (name) => {
    try {
      if (typeof scope?.[name] === 'function') return scope[name].bind(scope);
      if (typeof scope?.TavernHelper?.[name] === 'function') {
        return scope.TavernHelper[name].bind(scope.TavernHelper);
      }
    } catch {}
    return null;
  };

  const messageId = () => {
    const value = safeCall(callable('getCurrentMessageId'));
    return Number.isInteger(value) ? value : null;
  };

  const messageOptions = () => ({
    type: 'message',
    message_id: messageId() ?? 'latest',
  });

  return Object.freeze({
    probe() {
      return {
        tavern: safeCall(callable('getTavernVersion')),
        helper: safeCall(callable('getTavernHelperVersion')),
        messageId: messageId(),
        hasGetVariables: Boolean(callable('getVariables')),
        hasMvu: typeof scope?.Mvu?.getMvuData === 'function',
      };
    },

    async ready(timeoutMs = 2500) {
      if (scopeHasRuntime(scope)) return this.probe();
      const wait = callable('waitGlobalInitialized');
      if (!wait) return this.probe();
      let timer;
      try {
        await Promise.race([
          Promise.resolve(wait('Mvu')),
          new Promise((resolve) => {
            timer = setTimeout(resolve, Math.max(0, timeoutMs));
          }),
        ]);
      } catch {}
      clearTimeout(timer);
      return this.probe();
    },

    async read(lastGood = null) {
      const errors = [];
      const options = messageOptions();
      const getVariables = callable('getVariables');

      if (getVariables) {
        try {
          const data = await Promise.resolve(getVariables(options));
          if (data?.stat_data && typeof data.stat_data === 'object') {
            return { status: 'ready', statData: data.stat_data, source: 'getVariables' };
          }
          errors.push('Tavern Helper 返回的数据不含 stat_data');
        } catch (error) {
          errors.push(asErrorMessage(error));
        }
      }

      try {
        const getMvuData = typeof scope?.Mvu?.getMvuData === 'function'
          ? scope.Mvu.getMvuData.bind(scope.Mvu)
          : null;
        if (getMvuData) {
          const data = await Promise.resolve(getMvuData(options));
          if (data?.stat_data && typeof data.stat_data === 'object') {
            return { status: 'ready', statData: data.stat_data, source: 'Mvu.getMvuData' };
          }
          errors.push('MVU 返回的数据不含 stat_data');
        }
      } catch (error) {
        errors.push(asErrorMessage(error));
      }

      if (lastGood && typeof lastGood === 'object') {
        return {
          status: 'stale',
          statData: lastGood,
          message: errors.join('；') || '变量接口暂不可用，正在显示上次读取的状态',
        };
      }

      return {
        status: 'unavailable',
        statData: {},
        message: errors.join('；') || '未检测到可用的 Tavern Helper 或 MVU 消息变量接口',
      };
    },

    subscribe(refresh) {
      const on = callable('eventOn');
      let events;
      try {
        events = scope?.Mvu?.events;
      } catch {
        events = null;
      }
      if (!on || !events || typeof refresh !== 'function') return () => {};

      const handles = [...new Set([
        events.VARIABLE_INITIALIZED,
        events.VARIABLE_UPDATE_ENDED,
      ].filter(Boolean))].flatMap((event) => {
        try {
          return [on(event, refresh)];
        } catch {
          return [];
        }
      });

      return () => {
        for (const handle of handles) {
          try {
            handle?.stop?.();
          } catch {}
        }
      };
    },
  });
}


